package com.vertex.restosphere.service.impl;

import static com.vertex.restosphere.service.impl.WorkspaceStoreImpl.*;
import com.vertex.restosphere.service.BillingWorkflow;
import com.vertex.restosphere.service.ReservationWorkflow;
import com.vertex.restosphere.service.WorkspaceSnapshots;
import com.vertex.restosphere.service.WorkspaceStore;
import com.vertex.restosphere.entity.*;
import com.vertex.restosphere.common.enums.Role;
import java.time.*;
import java.util.*;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;

@Service
@RequiredArgsConstructor
public class WorkspaceSnapshotsImpl implements WorkspaceSnapshots {
    private final WorkspaceStore db;
    private final ReservationWorkflow reservations;
    private final BillingWorkflow billing;
    static String str(Object o) {return Objects.toString(o,"");}
    @Override public Map<String,Object> snapshot(String workspace,User user) {
        var s=db.lock();db.flush();
        var data=map("schema",1,"version",1,"serviceVersion",1,"revision",s.getRevision(),"seedDay",LocalDate.now(ZoneId.of(s.getTimezone())),"nextId",s.getRevision()+1,"nextTicket",db.all(Order.class).size()+1);
        var staff=db.all(User.class).stream().filter(u->u.getRole()!=Role.CUSTOMER).map(u->staff(u,workspace)).toList();
        var areas=db.all(Area.class).stream().map(a->map("id",id(a),"name",a.getName())).toList();
        var tables=db.all(RestaurantTable.class).stream().map(t->map("id",id(t),"code",t.getCode(),"areaId",id(t.getArea()),"area",t.getArea().getName(),"capacity",t.getCapacity(),"seats",t.getCapacity(),"status",t.getStatus(),"sessionId",db.all(TableSession.class).stream().filter(x->x.getTable().equals(t)&&x.getStatus()!=TableSession.Status.CLOSED).map(WorkspaceStoreImpl::id).findFirst().orElse(null))).toList();
        var sessions=db.all(TableSession.class).stream().map(t->map("id",id(t),"tableId",id(t.getTable()),"reservationId",id(t.getReservation()),"waiterId",id(t.getWaiter()),"guests",t.getGuestCount(),"startedAt",t.getStartedAt(),"openedAt",t.getStartedAt(),"handedOverAt",t.getStartedAt(),"acceptedAt",t.getAcceptedAt(),"guestLeftAt",t.getGuestLeftAt(),"closedAt",t.getEndedAt(),"paymentRequested",t.getStatus()==TableSession.Status.PAYMENT_REQUESTED)).toList();
        var categories=db.all(MenuCategory.class).stream().map(c->map("id",id(c),"name",c.getName(),"visible",c.isVisible(),"sort",c.getSortOrder(),"sortOrder",c.getSortOrder(),"menuGroup",c.getMenuGroup())).toList();
        var menu=db.all(MenuItem.class).stream().map(i->map("id",id(i),"name",i.getName(),"categoryId",id(i.getCategory()),"price",i.getPrice(),"priceUnit",i.getPriceUnit(),"unit",i.getPriceUnit(),"image",str(i.getImageUrl()),"imageUrl",i.getImageUrl(),"description",str(i.getDescription()),"status",i.getStatus(),"updatedAt",i.getUpdatedAt())).toList();
        var orders=db.all(Order.class).stream().filter(o->o.getStatus()!=Order.Status.DRAFT).map(o->order(o,workspace)).toList();
        var items=db.all(OrderItem.class).stream().map(this::item).toList();
        var bills=db.all(Bill.class).stream().map(billing::view).toList();
        var approvals=db.all(ApprovalRequest.class).stream().map(this::approval).toList();
        var notifications=notifications(user);
        data.putAll(map("areas",areas,"tables",tables,"sessions",sessions,"tableSessions",sessions,"staff",staff,"employees",staff,"categories",categories,"menuCategories",categories,"menu",menu,"menuItems",menu,"orders",orders,"items",items,"orderItems",items,"bills",bills,"payments",db.all(Payment.class).stream().map(billing::payment).toList(),"approvals",approvals,"requests",workspace.equals("staff")?db.all(ApprovalRequest.class).stream().filter(r->r.getType()==ApprovalRequest.Type.CANCEL_ITEM).map(this::approval).toList():approvals,"notifications",notifications,"waiterNotifications",notifications,"outbox",db.all(Notification.class).stream().filter(n->n.getAudienceRole()!=null).map(n->notification(n)).toList(),"settings",reservations.settings(),"drafts",db.all(OrderDraft.class).stream().filter(d->d.getWaiter().equals(user)).map(d->map("id",id(d),"sessionId",id(d.getSession()),"waiterId",id(d.getWaiter()),"menuItemId",id(d.getMenuItem()),"quantity",d.getQuantity(),"note",str(d.getNote()))).toList(),"assignments",db.all(ReservationTable.class).stream().map(a->map("id",id(a),"reservationId",id(a.getReservation()),"tableId",id(a.getTable()),"assignedAt",a.getCreatedAt(),"releasedAt",reservations.active(a.getReservation())?null:a.getReservation().getUpdatedAt())).toList()));
        if(workspace.equals("cashier"))data.put("requests",db.all(ApprovalRequest.class).stream().filter(r->Set.of(ApprovalRequest.Type.DISCOUNT,ApprovalRequest.Type.BILL_ADJUSTMENT,ApprovalRequest.Type.PAYMENT_VOID).contains(r.getType())).map(this::approval).toList());
        data.put("reservations",db.all(Reservation.class).stream().map(r->{var v=reservations.view(r);if(workspace.equals("manager"))v.putAll(map("customer",r.getCustomerName(),"phone",r.getPhone(),"at",r.getStartsAt(),"until",r.getEndsAt(),"tableId",v.getOrDefault("tableId",""),"employeeId","","note",str(r.getNote())));return v;}).toList());
        data.put("incidents",db.all(Incident.class).stream().map(i->map("id",id(i),"code","I-"+id(i),"type",i.getType(),"severity",i.getSeverity(),"status",i.getStatus(),"title",i.getTitle(),"description",i.getDescription(),"orderId",i.getOrderItem()==null?null:id(i.getOrderItem().getOrder()),"itemId",i.getOrderItem()==null?null:id(i.getOrderItem()),"reporterId",id(i.getReporter()),"assigneeId",id(i.getAssignee()),"at",i.getCreatedAt(),"notifiedStaffIds",db.all(User.class).stream().filter(u->u.getRole()==Role.MANAGER).map(WorkspaceStoreImpl::id).toList(),"response",i.getResolution()==null?null:map("by",id(i.getAssignee()),"at",i.getUpdatedAt(),"text",i.getResolution()))).toList());
        data.put("menuRequests",db.all(ApprovalRequest.class).stream().filter(r->r.getType()==ApprovalRequest.Type.MENU_STATUS).map(r->map("id",id(r),"menuItemId",r.getTargetId(),"requested",r.getMenuStatus(),"requestedBy",id(r.getRequestedBy()),"requestedAt",r.getCreatedAt(),"status",r.getStatus(),"decidedAt",r.getDecidedAt(),"decidedBy",id(r.getDecidedBy()))).toList());
        data.put("history",db.all(AuditLog.class).stream().map(a->map("id",id(a),"at",a.getCreatedAt(),"actorId",id(a.getActor()),"entityId",a.getTargetId(),"text",a.getDescription())).toList());
        data.put("shifts",workspace.equals("cashier")?db.all(CashierShift.class).stream().map(x->map("id",id(x),"code","S-"+id(x),"cashierId",id(x.getCashier()),"status",x.getClosedAt()==null?"OPEN":"CLOSED","openedAt",x.getOpenedAt(),"openingFloat",x.getOpeningCash(),"closedAt",x.getClosedAt(),"expectedCash",x.getExpectedCash(),"countedCash",x.getCountedCash(),"closingNote",x.getNote())).toList():db.all(Shift.class).stream().map(this::shift).toList());
        data.put("scheduledShifts",db.all(ShiftAssignment.class).stream().filter(a->a.getUser().getRole()==Role.CASHIER).map(a->map("id",id(a.getShift()),"name",a.getShift().getName(),"start",a.getShift().getStartsAt(),"end",a.getShift().getEndsAt(),"cashierId",id(a.getUser()))).toList());
        data.put("config",map("restaurantName",s.getName(),"address",s.getAddress(),"serviceChargeRate",s.getServiceChargeRate().movePointRight(2),"taxRate",s.getVatRate().movePointRight(2),"methods",map("CASH",true,"TRANSFER",!str(s.getBankAccountNumber()).isEmpty(),"CARD",false),"bank",str(s.getBankAccountNumber()).isEmpty()?null:map("bankName",str(s.getBankName()),"accountNumber",s.getBankAccountNumber(),"accountName",str(s.getBankAccountName()))));
        if(((Map<?,?>)data.get("config")).get("bank")==null)((Map<String,Object>)data.get("config")).put("bank",null);
        data.put("counters",map("bill",bills.size(),"payment",db.all(Payment.class).size(),"request",approvals.size(),"shift",db.all(CashierShift.class).size(),"order",orders.size()));
        Map<String,Object> keys=new LinkedHashMap<>();db.all(Payment.class).stream().filter(p->id(user).equals(p.getCreatedBy())&&p.getIdempotencyKey()!=null).forEach(p->keys.put(p.getIdempotencyKey(),id(p)));data.put("processedKeys",keys);
        if(workspace.equals("manager")) {
            data.put("bills",db.all(Bill.class).stream().filter(b->b.getStatus()==Bill.Status.PAID).map(b->map("id",id(b),"at",b.getPaidAt(),"shift",b.getPaidAt().atZone(ZoneId.of(s.getTimezone())).getHour()<16?"LUNCH":"DINNER","guests",b.getSession().getGuestCount(),"discount",b.getDiscount(),"items",billing.items(b).stream().filter(i->!Set.of(OrderItem.Status.CANCELLED,OrderItem.Status.VOIDED,OrderItem.Status.REJECTED).contains(i.getStatus())).map(i->map("name",i.getItemName(),"categoryId",id(i.getMenuItem().getCategory()),"quantity",i.getQuantity(),"unitPrice",i.getUnitPrice())).toList())).toList());
            data.put("payments",db.all(Payment.class).stream().map(p->map("id",id(p),"billId",id(p.getBill()),"at",p.getPaidAt()==null?p.getCreatedAt():p.getPaidAt(),"method",p.getMethod(),"amount",p.getAmount(),"status",p.getStatus()==Payment.Status.COMPLETED?"COMPLETED":p.getStatus()==Payment.Status.PENDING?"PENDING":"FAILED")).toList());
        }
        if(workspace.equals("admin"))return admin(s);
        Set<String> fields=switch(workspace) {
            case "kitchen" -> Set.of("schema","seedDay","revision","nextId","nextTicket","staff","orders","items","menuCategories","menuItems","menuRequests","incidents","notifications","outbox");
            case "cashier" -> Set.of("schema","seedDay","revision","nextId","counters","config","staff","menu","tables","sessions","orders","items","bills","payments","requests","shifts","scheduledShifts","notifications","outbox","processedKeys");
            case "manager" -> Set.of("schema","revision","seedDay","areas","tables","sessions","reservations","orders","employees","shifts","categories","menu","approvals","incidents","notifications","bills","payments","history","outbox");
            default -> Set.of("version","serviceVersion","revision","settings","seedDay","areas","tables","reservations","notifications","assignments","nextId","employees","tableSessions","menuCategories","menuItems","orders","orderItems","drafts","bills","waiterNotifications","requests","outbox");
        };
        data.keySet().retainAll(fields);
        data.put("outbox",db.all(Notification.class).stream().filter(n->n.getAudienceRole()==user.getRole()||user.equals(n.getRecipient())).map(this::notification).toList());
        return data;
    }
    Map<String,Object> staff(User u,String workspace) {
        List<String> permissions=switch(workspace){case "cashier"->List.of("bills.view","bills.prepare","payments.create","payments.view","payments.confirm_transfer","receipts.print","transactions.view","discounts.apply","discounts.request","requests.create","shifts.view","shifts.manage");case "kitchen"->List.of("kitchen.items.update","kitchen.incidents.create","kitchen.menu.availability");default->List.of("tables.edit","reservations.edit","employees.assign","shifts.manage","menu.manage","approvals.decide","incidents.manage","reports.export");};
        return map("id",id(u),"name",u.getFullName(),"fullName",u.getFullName(),"username",u.getEmail(),"role",u.getRole(),"position",u.getRole().name(),"shift",db.all(ShiftAssignment.class).stream().filter(a->a.getUser().equals(u)&&a.getShift().getStartsAt().isBefore(Instant.now())&&a.getShift().getEndsAt().isAfter(Instant.now())).map(a->a.getShift().getName()).findFirst().orElse(""),"permissions",permissions,"discountLimitPercent",10,"approvalLimit",999999999999L,"department",switch(u.getRole()){case WAITER->"SERVICE";case KITCHEN->"KITCHEN";case CASHIER->"CASHIER";case RECEPTIONIST->"RECEPTION";default->"MANAGEMENT";},"status",u.isEnabled()?"ACTIVE":"INACTIVE","areaId",id(u.getAssignedArea()));
    }
    Map<String,Object> order(Order o,String workspace) {var t=o.getSession().getTable();return map("id",id(o),"code","O-"+id(o),"sessionId",id(o.getSession()),"tableCode",t.getCode(),"area",t.getArea().getName(),"guests",o.getSession().getGuestCount(),"waiterId",id(o.getWaiter()),"employeeId",id(o.getWaiter()),"sequence",o.getRoundNumber(),"round",o.getRoundNumber(),"submittedAt",o.getCreatedAt(),"at",o.getCreatedAt(),"paid",billing.bill(o.getSession()).getStatus()==Bill.Status.PAID,"priority",o.getPriorityAt()==null?null:map("at",o.getPriorityAt(),"by",o.getPriorityBy(),"reason",o.getPriorityReason()),"items",db.all(OrderItem.class).stream().filter(i->i.getOrder().equals(o)).map(this::item).toList());}
    Map<String,Object> item(OrderItem i) {return map("id",id(i),"orderId",id(i.getOrder()),"menuItemId",id(i.getMenuItem()),"menuId",id(i.getMenuItem()),"name",i.getItemName(),"unitPrice",i.getUnitPrice(),"quantity",i.getQuantity(),"note",str(i.getNote()),"status",i.getStatus(),"version",i.getVersion(),"submittedAt",i.getCreatedAt(),"startedAt",i.getStartedAt(),"startedBy",id(i.getChef()),"chefId",id(i.getChef()),"readyAt",i.getReadyAt(),"readyBy",id(i.getChef()),"servedAt",i.getServedAt(),"rejectionReason",i.getRejectionReason(),"cancellationReason",i.getRejectionReason(),"history",db.all(AuditLog.class).stream().filter(a->i.getId().equals(a.getTargetId())).map(a->map("at",a.getCreatedAt(),"by",id(a.getActor()),"status",switch(a.getAction()){case "start"->"PREPARING";case "complete"->"READY";case "reject"->"REJECTED";default->i.getStatus().name();},"note",a.getDescription())).toList());}
    Map<String,Object> approval(ApprovalRequest r) {
        Bill b=null;OrderItem item=null;Payment payment=null;
        if("BILL".equals(r.getTargetType()))b=db.get(Bill.class,r.getTargetId().toString());
        if("ORDER_ITEM".equals(r.getTargetType())){item=db.get(OrderItem.class,r.getTargetId().toString());b=billing.bill(item.getOrder().getSession());}
        if("PAYMENT".equals(r.getTargetType())){payment=db.get(Payment.class,r.getTargetId().toString());b=payment.getBill();}
        return map("id",id(r),"code","R-"+id(r),"type",r.getType(),"status",r.getStatus(),"targetType",r.getTargetType(),"targetId",r.getTargetId(),"billId",b==null?null:id(b),"paymentId",payment==null?null:id(payment),"itemId",item==null?null:id(item),"sessionId",b==null?null:id(b.getSession()),"amount",r.getAmount(),"menuStatus",r.getMenuStatus(),"discount",r.getDiscountValue()==null?null:map("mode",r.getDiscountMode(),"value",r.getDiscountValue(),"amount",r.getAmount()),"reason",r.getReason(),"requestedBy",id(r.getRequestedBy()),"requestedAt",r.getCreatedAt(),"decidedBy",r.getDecidedBy()==null?null:id(r.getDecidedBy()),"decidedAt",r.getDecidedAt(),"decisionNote",r.getDecisionNote());
    }
    Map<String,Object> shift(Shift s) {var zone=ZoneId.of(db.lock().getTimezone());return map("id",id(s),"name",s.getName(),"date",s.getStartsAt().atZone(zone).toLocalDate(),"start",s.getStartsAt().atZone(zone).toLocalTime().toString(),"end",s.getEndsAt().atZone(zone).toLocalTime().toString(),"minimum",s.getMinimumStaff(),"employeeIds",db.all(ShiftAssignment.class).stream().filter(a->a.getShift().equals(s)).map(a->id(a.getUser())).toList());}
    List<Map<String,Object>> notifications(User user) {return db.all(Notification.class).stream().filter(n->n.getAudienceRole()==user.getRole()||user.equals(n.getRecipient())).map(this::notification).toList();}
    Map<String,Object> notification(Notification n) {
        String target=n.getPath();boolean decision="REQUEST_DECIDED".equals(n.getKind());
        String path=n.getAudienceRole()==Role.MANAGER?"/staff/manager/"+("INCIDENT".equals(n.getKind())?"incidents":"approvals")+"?id="+str(target):str(target);
        return map("id",id(n),"kind",n.getKind(),"title",n.getTitle(),"body",n.getBody(),"at",n.getCreatedAt(),"path",path,"audience",n.getAudienceRole(),"staffId",id(n.getRecipient()),"targetId",target,"requestId",decision?target:null,"sessionId",n.getAudienceRole()==Role.WAITER?target:null,"billId",n.getAudienceRole()==Role.CASHIER&&!decision?target:null,"orderId",n.getAudienceRole()==Role.KITCHEN&&Set.of("NEW_ORDER","PRIORITY").contains(n.getKind())?target:null,"readBy",db.all(NotificationRead.class).stream().filter(r->r.getNotification().equals(n)).map(r->id(r.getUser())).toList());
    }
    Map<String,Object> admin(RestaurantSettings s) {return map("users",db.all(User.class).stream().map(u->map("id",id(u),"fullName",u.getFullName(),"email",u.getEmail(),"role",u.getRole(),"status",u.isEnabled()?"ACTIVE":"LOCKED","createdAt",u.getCreatedAt(),"initials",u.getFullName().substring(0,1).toUpperCase())).toList(),"restaurant",map("name",s.getName(),"description",str(s.getDescription()),"address",str(s.getAddress()),"hotline",str(s.getPhone()),"email",str(s.getEmail()),"openingHours",str(s.getOpeningHours()),"facebook",str(s.getFacebook()),"instagram",str(s.getInstagram()),"tiktok",str(s.getTiktok()),"logoUrl",str(s.getLogoUrl()),"coverUrl",str(s.getCoverUrl())),"settings",map("onlineReservations",s.isOnlineReservations(),"tableHoldMinutes",s.getHoldMinutes(),"noShowMinutes",s.getNoShowMinutes(),"bufferMinutes",s.getBufferMinutes(),"billing",map("serviceChargePercent",s.getServiceChargeRate(),"vatPercent",s.getVatRate(),"bankAccount",str(s.getBankAccountNumber())),"timezone",s.getTimezone(),"currency",s.getCurrency(),"emailNotifications",s.isEmailNotifications()),"auditLogs",db.all(AuditLog.class).stream().filter(a->Set.of("ROLE_CHANGED","ACCOUNT_LOCKED","ACCOUNT_UNLOCKED","RESTAURANT_UPDATED").contains(a.getAction())).map(a->map("id",id(a),"at",a.getCreatedAt(),"actor",a.getActor()==null?"System":a.getActor().getFullName(),"action",a.getAction(),"target",a.getDescription(),"result","SUCCESS")).toList());}
}
